-- Fill the existing Medical / Healthcare Virtual Assistant course with substantive
-- administrative training content. The course remains draft and every lesson
-- remains unpublished until reviewer approval.

update public.training_courses
set status='draft',
    published_at=null,
    reviewed_by=null,
    last_reviewed_at=null,
    estimated_minutes=300,
    updated_at=now()
where slug='medical-healthcare-virtual-assistant';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Define the administrative role of a Healthcare Virtual Assistant","Separate routine administrative work from clinical judgment","Recognize decisions that must stay with clinicians, billers, compliance staff, or the client","Build a clear escalation map before you begin patient-facing work"]},{"type":"heading","text":"The role is operational, not clinical"},{"type":"paragraph","text":"A Healthcare Virtual Assistant can help a practice move information, appointments, documents, billing status, referrals, and patient requests through an approved workflow. The VA supports the system around care. The VA does not become the person who diagnoses, interprets symptoms, selects treatment, prescribes, changes a care plan, or decides what a patient medically needs."},{"type":"heading","text":"Common administrative responsibilities"},{"type":"list","items":["Scheduling and rescheduling appointments according to clinic rules","Sending approved reminders and administrative follow-ups","Collecting demographic and insurance information the practice has asked for","Routing referrals, forms, records, and messages to the correct queue","Tracking billing or claim status without making coding or coverage decisions","Updating approved practice-management fields and documenting administrative actions","Preparing factual handoffs so clinicians and office staff can continue the work"]},{"type":"heading","text":"Decisions a VA should not make"},{"type":"list","items":["Whether a symptom is dangerous, normal, or urgent","Which clinician, specialty, medication, test, or treatment a patient needs unless the practice has a fixed administrative routing rule","How a clinical note should be changed to support a claim","Which diagnostic or procedure code should be used unless a qualified person has already provided the code and the VA is only entering it","Whether a patient legally qualifies for a regulated service, benefit, accommodation, or exception","Whether confidential information may be disclosed when the request falls outside the client''s approved policy"]},{"type":"heading","text":"Build your authority map"},{"type":"steps","items":["List the workflows you are expected to support.","For each workflow, mark actions you may complete without approval.","Mark actions that require a clinician, biller, manager, or compliance owner.","Write the exact escalation channel for urgent, privacy, billing, and patient-complaint issues.","Keep approved scripts, templates, and SOPs linked from the source system.","When the real situation falls outside the documented rule, stop and escalate instead of inventing a new rule."]},{"type":"callout","title":"Administrative confidence is not clinical authority","text":"A VA can become very familiar with healthcare terminology and workflows. Familiarity should make routing faster and safer, not tempt the VA to make decisions reserved for licensed or authorized staff."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Answering a medical question because the answer seems obvious","Telling a patient a result is fine because it is within a range shown on screen","Changing a visit type to solve a scheduling problem without checking the clinic rule","Promising a refund, insurance payment, prescription, referral, or callback outcome","Using a previous patient''s case as a shortcut for a new patient''s situation"]},{"type":"scenario","title":"Practice scenario","text":"A patient calls to move an appointment and adds, ''My symptoms are worse today. Do you think I can wait until Friday?'' The calendar has openings on Friday. Explain which part of the request you can handle administratively, what you should not answer, and how you would escalate the clinical statement using the practice''s approved protocol."},{"type":"heading","text":"QA before you close the task"},{"type":"list","items":["Did I stay inside the authority documented for this role?","Did I put the request in the correct system and queue?","Did I preserve the patient''s exact meaning instead of rewriting it as a clinical conclusion?","Did I identify the next owner and time-sensitive follow-up?","Could another staff member understand what happened from the record I left?"]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Healthcare VA work is high-trust administrative work.","Move routine work forward confidently when the SOP is clear.","Do not diagnose, interpret, prescribe, or make regulated decisions.","Escalation skill is part of competence, not a sign of weakness."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000011';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize why health information needs stronger handling than ordinary admin data","Use role-based and minimum-necessary access as practical operating principles","Keep patient information inside approved systems and channels","Respond correctly to accidental exposure or suspicious access"]},{"type":"heading","text":"Health information is high-sensitivity data"},{"type":"paragraph","text":"Patient records may contain identity details, contact information, diagnoses, medications, appointment history, insurance data, payment information, clinical notes, referrals, test information, and other sensitive details. A VA should never treat access to the system as permission to browse everything in it."},{"type":"heading","text":"Jurisdiction matters"},{"type":"paragraph","text":"Healthcare privacy rules depend on the country, organization, contract, and role. In US HIPAA-covered workflows, HHS distinguishes covered entities and business associates and requires safeguards for protected health information. HHS also describes a minimum-necessary principle for many uses, disclosures, and requests, with exceptions such as certain treatment disclosures. A VA should follow the client''s approved policy and access design rather than trying to interpret the law case by case."},{"type":"heading","text":"Practical minimum-necessary habits"},{"type":"list","items":["Open only the patient record needed for the assigned task.","Use the least permission level that lets you do the job.","Do not download an entire patient list to work on a handful of records.","Do not copy clinical details into Slack, personal notes, spreadsheets, AI tools, or email unless the workflow explicitly authorizes that channel.","Use approved secure portals or systems for records and patient messages.","Close or lock access when you step away from the device."]},{"type":"heading","text":"Remote-work safeguards"},{"type":"steps","items":["Use the client''s approved device, browser profile, VPN, password manager, and multi-factor authentication requirements.","Keep work accounts separate from personal accounts.","Avoid shared household devices unless the client explicitly permits and secures them.","Store temporary files only where the client allows and delete them according to policy after use.","Do not photograph patient information with a phone for convenience.","Report lost devices, suspicious sign-ins, wrong-recipient messages, and accidental sharing immediately."]},{"type":"callout","title":"Do not paste patient data into unapproved AI tools","text":"Even when AI can summarize a record quickly, the privacy and security decision comes first. Use only tools and workflows the healthcare client has explicitly approved for the information involved."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Searching a patient because you recognize the name","Keeping screenshots of records in a personal downloads folder","Using a public share link because the authorized recipient cannot open the secure link","Sending a full chart when the approved request needs only one document","Trying to quietly recall or delete a misdirected message without reporting the incident"]},{"type":"scenario","title":"Practice scenario","text":"You are asked to confirm contact details for 20 patients scheduled tomorrow. The exported file also contains diagnoses, medications, balances, and clinical notes. Explain how you would reduce the data you handle, where you would perform the work, and what you would do if the export cannot be limited."},{"type":"heading","text":"If an incident happens"},{"type":"steps","items":["Stop further disclosure if you can do so safely.","Do not erase the audit trail or hide what happened.","Record the facts: what information, which recipient or system, when, and what action was taken.","Notify the client''s designated privacy or security owner immediately.","Follow the client''s incident-response instructions rather than inventing your own legal response."]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Access is task-specific, not curiosity-based.","Use the smallest practical amount of patient information for the administrative purpose.","Keep health data inside approved systems.","Report incidents quickly and factually."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000012';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Collect patient intake information consistently","Verify demographics without turning the process into interrogation","Handle discrepancies without overwriting uncertain data","Prepare a clean administrative handoff for the clinical team"]},{"type":"heading","text":"Intake is a data-quality workflow"},{"type":"paragraph","text":"The goal of patient intake is to collect the information the practice needs before the visit and place it in the correct fields. Accurate demographics reduce failed reminders, duplicate charts, claim problems, and wasted clinician time. The VA should collect and route information, not evaluate the medical meaning of the patient''s answers."},{"type":"heading","text":"Typical administrative fields"},{"type":"list","items":["Legal or preferred name according to practice policy","Date of birth or other approved identity fields","Phone, email, address, and communication preference","Emergency or authorized contact where the practice requires it","Insurance or payer details when relevant","Referring provider or source when relevant","Consent, intake, and policy acknowledgements tracked by status","Reason for visit captured using the practice''s approved wording or patient-provided description"]},{"type":"heading","text":"Verification workflow"},{"type":"steps","items":["Open the correct patient record or begin the approved new-patient process.","Use the practice''s identity-verification questions before discussing account details.","Compare new information with existing demographics.","If information conflicts, confirm the field with the patient rather than guessing which version is correct.","Enter the information into the designated fields instead of burying it in free-text notes.","Flag clinical answers, consent exceptions, or documentation gaps for the designated staff member.","Record what remains incomplete and who owns the next step."]},{"type":"callout","title":"Preserve the patient''s wording","text":"If the patient describes symptoms or a medical concern, record or route the message according to the clinic''s process. Do not translate the statement into a diagnosis or clinical conclusion."},{"type":"heading","text":"Duplicate-record risk"},{"type":"paragraph","text":"Creating a second chart for an existing patient can split history and cause downstream errors. Search using the practice''s approved identifiers before creating a new record. If two records may belong to the same patient, do not merge them unless the workflow and your permissions specifically allow it."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Creating a new record because the spelling is slightly different","Replacing an old address without confirming the patient","Copying demographic data from an unverified referral into verified fields","Marking forms complete when required sections are blank","Adding personal commentary about the patient''s behaviour or condition"]},{"type":"scenario","title":"Practice scenario","text":"A new online intake appears to match an existing patient by name and phone, but the date of birth differs by one digit and the address is new. Describe the checks you would perform, what you would document, and why you should not simply create a second record."},{"type":"heading","text":"QA checklist"},{"type":"list","items":["Identity fields were verified using the approved process.","Required administrative fields are complete or visibly outstanding.","No uncertain information was silently overwritten.","Clinical content was routed, not interpreted.","The next owner can see what still needs action."]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Good intake is accurate, minimal, and traceable.","Use structured fields when the system provides them.","Confirm discrepancies instead of guessing.","Keep clinical interpretation with clinical staff."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000021';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track incoming and outgoing referrals without losing documents","Route records to the correct person and system","Identify administrative gaps before they block care","Escalate clinical or authorization decisions rather than making them"]},{"type":"heading","text":"A referral is a chain of custody"},{"type":"paragraph","text":"Referral work often involves several handoffs: sender, receiving practice, patient, clinician, records team, payer, or another provider. The administrative goal is to make the status visible: received, missing information, under review, scheduled, sent, confirmed, or closed according to the practice''s workflow."},{"type":"heading","text":"Incoming referral workflow"},{"type":"steps","items":["Confirm the referral belongs to the correct practice and patient.","Save the document in the approved record location.","Capture the referring provider and contact details when required.","Check only the administrative completeness rules documented by the practice.","Route clinical review questions to the designated clinician or triage queue.","Create the next action, owner, and due date.","Document attempts to obtain missing information."]},{"type":"heading","text":"Outgoing document workflow"},{"type":"steps","items":["Verify the intended recipient and approved delivery channel.","Confirm the patient and document set match the request.","Use the client''s authorization or consent workflow where required.","Send only the approved documents.","Record the date, destination, method, and status.","Track confirmation or follow-up when the SOP requires it."]},{"type":"callout","title":"Administrative completeness is not clinical sufficiency","text":"You may be allowed to check that a referral contains required pages, provider details, or a signed form. That does not mean you decide whether the clinical information is adequate for treatment or whether the patient medically qualifies."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Saving referral files only in email instead of the patient record","Sending records to an old provider address without verification","Closing a referral because the patient has not answered once","Guessing which specialist should receive a clinically ambiguous referral","Sending extra records ''just in case'' instead of the approved document set"]},{"type":"scenario","title":"Practice scenario","text":"An incoming referral has the patient''s demographics and referring provider, but the attachment named ''clinical notes'' is missing. The patient is asking when they can book. Show the administrative actions you can take, the status you would record, and the question that belongs with the clinical/referral team."},{"type":"heading","text":"Referral tracker fields"},{"type":"list","items":["Patient or record identifier","Referral source and destination","Received or sent date","Administrative status","Missing items","Current owner","Next follow-up date","Outcome or closure reason allowed by the SOP"]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Keep every referral status visible.","Verify destinations before sending records.","Track missing documents with an owner and follow-up date.","Do not make clinical acceptance or specialty decisions."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000022';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Schedule patients using visit-type rules instead of guesswork","Protect clinician capacity and required buffers","Handle telehealth, locations, and prerequisites accurately","Recognize when a scheduling request needs clinical review"]},{"type":"heading","text":"A healthcare calendar encodes operational rules"},{"type":"paragraph","text":"Appointments are not interchangeable blocks of time. Different visit types can require different clinicians, durations, rooms, equipment, preparation, forms, referral status, or follow-up rules. A reliable VA schedules from the clinic''s appointment matrix or SOP rather than choosing whatever opening looks convenient."},{"type":"heading","text":"Before booking"},{"type":"list","items":["Confirm the correct patient record.","Identify the approved visit type from the request or staff instruction.","Check clinician, location, duration, and resource requirements.","Check whether the workflow requires forms, referral review, deposit, authorization, or other administrative prerequisites.","Confirm the patient''s time zone for telehealth or cross-region appointments.","Check whether the practice allows waitlist or same-day scheduling for that visit type."]},{"type":"heading","text":"Scheduling workflow"},{"type":"steps","items":["Find slots that meet the visit rules.","Offer only times you are authorized to offer.","Repeat the confirmed date, time, location or telehealth method, and arrival instructions.","Attach or trigger the approved forms and reminders.","Record any special administrative request exactly and route it to the right person.","Update the source system immediately so the slot is not double-booked."]},{"type":"callout","title":"Do not turn symptoms into a scheduling decision","text":"If a patient describes symptoms, asks whether it is safe to wait, or requests a visit type you cannot determine administratively, use the clinic''s clinical escalation process. Do not choose urgency from your own judgment."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Booking the right clinician for the wrong visit duration","Moving a patient into a protected slot without authority","Assuming a follow-up and a new-patient visit are interchangeable","Sending a telehealth link without checking the correct patient and appointment","Manually converting time zones without checking the actual appointment date"]},{"type":"scenario","title":"Practice scenario","text":"A patient requests the first available appointment and says they are willing to see anyone. The next open slot is a short follow-up slot, but the patient appears to be new to the practice. Explain what you verify before booking and what you do if the appointment rules do not clearly cover the situation."},{"type":"heading","text":"Calendar QA"},{"type":"list","items":["Correct patient","Correct visit type","Correct clinician and location","Correct duration and resources","Required forms or prerequisites triggered","Time zone clear","Notes factual and non-clinical","Confirmation sent through approved channel"]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Schedule from rules, not empty space.","Make telehealth and location details unambiguous.","Protect restricted slots and prerequisites.","Escalate clinical urgency instead of guessing."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000031';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Run reminders, recalls, reschedules, and no-show workflows consistently","Protect privacy in voicemail, SMS, and email","Use waitlists without creating duplicate promises","Keep follow-up visible until the workflow is complete"]},{"type":"heading","text":"These are different workflows"},{"type":"paragraph","text":"A reminder tells a patient about an existing appointment. A recall asks a patient to return according to an approved follow-up process. A reschedule changes an appointment. A no-show workflow records that the patient did not attend and triggers the practice''s next step. Mixing these processes can create missed care, billing problems, or confusing messages."},{"type":"heading","text":"Reminder workflow"},{"type":"steps","items":["Confirm the appointment details in the source system.","Use the approved reminder channel and template.","Limit message content to what the practice permits for that channel.","Record delivery failures when the system exposes them.","Escalate repeated delivery problems if the clinic requires another contact method."]},{"type":"heading","text":"Reschedule and waitlist workflow"},{"type":"steps","items":["Confirm which appointment is being changed.","Apply cancellation-window or deposit rules only as documented.","Release or hold the original slot according to the SOP.","Book the new slot using normal visit rules.","If using a waitlist, contact patients in the approved order and avoid promising one slot to multiple people.","Update reminders so the old appointment does not continue generating messages."]},{"type":"callout","title":"Recall does not mean clinical interpretation","text":"A VA may run an approved recall list or contact patients using an approved script. The VA should not explain why a clinical result requires follow-up unless the clinician or approved script provides that wording."},{"type":"heading","text":"No-show workflow"},{"type":"list","items":["Record the no-show using the correct status.","Apply approved administrative follow-up steps.","Do not shame or speculate about why the patient missed the visit.","Do not waive fees, apply penalties, or promise exceptions unless authorized.","Escalate repeated or clinically sensitive follow-up according to the practice rule."]},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Leaving detailed medical information in voicemail","Sending the old appointment reminder after rescheduling","Promising a waitlist patient a slot before it is secured","Using the same no-show message for every context","Closing a recall task because one call was unanswered"]},{"type":"scenario","title":"Practice scenario","text":"A patient missed yesterday''s appointment, has an outstanding recall task, and now leaves a voicemail asking to rebook next month. Explain how you separate the no-show, recall, and rescheduling actions without interpreting the clinical reason for the recall."},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Use the correct workflow type.","Keep reminder content privacy-safe.","Make waitlist ownership explicit.","Do not let recalls disappear after one failed contact attempt unless the SOP says the workflow is complete."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000032';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support billing workflows without acting as a coder or financial decision-maker","Track patient balances and invoice status accurately","Handle payment follow-up professionally","Protect payment information and route disputes correctly"]},{"type":"heading","text":"Billing admin is about status and evidence"},{"type":"paragraph","text":"A Healthcare VA may help prepare invoices from approved charges, send statements, record payment status, follow up outstanding balances, or route billing questions. The VA should not invent fees, alter clinical coding, promise insurer payment, or decide write-offs and discounts unless those actions are explicitly authorized."},{"type":"heading","text":"Routine billing tasks"},{"type":"list","items":["Confirm approved charge or invoice data is present","Send invoices or statements using the practice''s system","Record payment status and reference numbers","Send approved payment reminders","Identify duplicate charges or obviously missing administrative fields for review","Route coding, coverage, discount, refund, write-off, and financial-hardship decisions to the designated owner"]},{"type":"heading","text":"Payment follow-up workflow"},{"type":"steps","items":["Review the account history before contacting the patient.","Confirm the balance and status come from the source system.","Use the approved reminder template and channel.","State the amount, due status, and payment method without adding threats or promises.","If the patient disputes the charge, pause scripted chasing and route the dispute with context.","Record the interaction and next follow-up date."]},{"type":"callout","title":"Do not collect card details in an unapproved channel","text":"Use only the payment method and processor approved by the practice. Do not ask patients to send card numbers through ordinary email, chat, spreadsheets, or personal messaging."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing a fee because the patient says it is wrong without checking the authorized owner","Assuming an insurer will pay because a similar claim was paid before","Deleting or overwriting the original invoice after a correction","Sending aggressive reminders without reviewing an active dispute","Copying payment data into task notes for convenience"]},{"type":"scenario","title":"Practice scenario","text":"A patient says an invoice is wrong because they were told the visit would cost less. The system shows the current invoice but no note about the quoted amount. Write the administrative response structure, what evidence you would look for, and who should decide whether the invoice changes."},{"type":"heading","text":"Useful billing tracker fields"},{"type":"list","items":["Invoice or account reference","Date issued","Current balance","Payment status","Last patient contact","Dispute or exception flag","Current owner","Next follow-up date"]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Track billing status accurately.","Use approved payment channels.","Route coding, refunds, discounts, and coverage decisions.","Document disputes instead of arguing with the patient."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000041';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand the administrative lifecycle of a healthcare claim","Distinguish correctable admin errors from coding or clinical decisions","Track payer responses and remittances without losing ownership","Build an exception queue that can be worked systematically"]},{"type":"heading","text":"Think in statuses, not assumptions"},{"type":"paragraph","text":"Claims workflows vary by country, payer, practice, and specialty. A VA does not need to become a coding expert to support the workflow. The useful skill is knowing what was submitted, what status came back, what information is missing, who is authorized to correct it, and when the next follow-up is due."},{"type":"heading","text":"A generic claim lifecycle"},{"type":"steps","items":["Confirm the encounter or bill has the approved information required for submission.","Submit only through the practice''s authorized workflow if that is part of your role.","Record submission date and reference.","Check status using the approved portal, clearinghouse, or payer channel.","Classify the response into an administrative category such as pending, accepted, rejected, denied, paid, partially paid, or information requested according to the client''s system.","Route coding, medical-necessity, documentation, or coverage decisions to the qualified owner.","Track resubmission or follow-up until the item is resolved or formally closed."]},{"type":"heading","text":"Administrative versus specialist corrections"},{"type":"list","items":["Administrative: missing subscriber ID, wrong address, obvious demographic mismatch, missing attachment already supplied, duplicate submission reference.","Specialist/authorized review: diagnosis or procedure coding, modifier selection, medical necessity, clinical documentation changes, coverage interpretation, appeal argument, or changing the service recorded."]},{"type":"callout","title":"Do not change clinical documentation to make a claim pay","text":"If a payer response suggests missing or insufficient clinical information, route the issue to the authorized clinician, coder, biller, or revenue-cycle owner. The VA can track the exception but should not rewrite the care record."},{"type":"heading","text":"Remittance and payment posting support"},{"type":"paragraph","text":"Where authorized, a VA may help match payer responses or remittances to accounts, record administrative status, and identify discrepancies for review. The practice''s billing owner should define what fields the VA may post and which variances require specialist review."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Calling every non-payment a denial","Resubmitting repeatedly without understanding the rejection reason","Changing codes to copy a previously paid claim","Closing an exception after leaving one payer message","Failing to link the payer response or reference to the tracked item"]},{"type":"scenario","title":"Practice scenario","text":"Two claims return problems. Claim A is rejected because the subscriber ID is missing. Claim B is denied for a reason that references medical necessity. Explain what you can fix on Claim A if the verified ID is available, what you should not change on Claim B, and how both items should be tracked."},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Keep claim status and next owner visible.","Correct only administrative fields you are authorized to correct.","Do not make coding or medical-necessity decisions.","Use exception tracking so unresolved claims do not disappear."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000042';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Respond to administrative patient requests clearly and safely","Verify identity before discussing account-specific details","Separate status information from clinical interpretation","Write messages that leave a clear next step"]},{"type":"heading","text":"Administrative communication should reduce uncertainty"},{"type":"paragraph","text":"Patients often contact a practice for scheduling, forms, records, billing status, referral status, portal help, directions, or general process questions. A good administrative reply states what is confirmed, what action has been taken, what information is still needed, and what happens next."},{"type":"heading","text":"Before discussing an account"},{"type":"steps","items":["Use the practice''s identity-verification process for the channel.","Check authorized representatives or communication preferences when relevant.","Open the correct patient record.","Read the recent thread or history before replying.","Use only the approved channel for the information involved."]},{"type":"heading","text":"A useful message structure"},{"type":"steps","items":["Lead with the confirmed administrative status.","State the action already taken.","Ask for only the missing information required to continue.","Give the next step and expected administrative timeline if the practice has one.","Route clinical questions separately rather than answering them inside the admin reply.","Record the interaction in the source system."]},{"type":"callout","title":"A result can be visible without being yours to explain","text":"If a patient asks what a test result means, whether a medication is working, or whether a symptom is normal, do not interpret the information. Route the question to the clinical team according to the practice''s process."},{"type":"heading","text":"Common patient requests a VA may handle"},{"type":"list","items":["Appointment availability and approved scheduling changes","Status of a referral, form, or records request","How to use the approved patient portal","Administrative preparation instructions copied from an approved template","Invoice or payment status","Confirmation that a message has been sent to the clinical team"]},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Starting with a long apology instead of the actual status","Promising when a clinician will call back without confirmed capacity","Explaining a result because it looks straightforward","Sending sensitive details before completing identity verification","Using personal email or messaging when the patient cannot access the approved channel"]},{"type":"scenario","title":"Practice scenario","text":"A patient sends: ''I saw my result in the portal. Is this bad? Also, can you move my appointment to Tuesday?'' Draft the administrative response structure. Show how you can handle scheduling while routing the clinical question without sounding dismissive."},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Verify identity and channel first.","Lead with confirmed facts.","Handle the administrative part you own.","Route clinical interpretation to clinical staff."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000051';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize messages that should leave the routine admin queue immediately","Use escalation protocols without attempting clinical triage","Handle complaints and safety-sensitive messages factually","Document urgent handoffs so responsibility is clear"]},{"type":"heading","text":"Escalation is a workflow, not a diagnosis"},{"type":"paragraph","text":"A Healthcare VA may receive messages describing worsening symptoms, medication concerns, threats, self-harm, abuse, severe distress, urgent care needs, privacy incidents, or serious complaints. The VA''s job is not to decide what the condition is. The job is to recognize that the message falls outside routine administration and activate the clinic''s approved escalation process immediately."},{"type":"heading","text":"Build an escalation matrix before the shift starts"},{"type":"list","items":["Clinical concern or symptom question","Potential emergency or immediate safety concern","Medication or prescription request","Test-result interpretation request","Safeguarding, abuse, self-harm, or threat statement","Privacy or security incident","Complaint involving harm, legal threat, regulator, or media","Billing or refund dispute outside delegated authority"]},{"type":"heading","text":"Escalation workflow"},{"type":"steps","items":["Keep the patient''s wording as accurately as possible.","Do not minimize, reinterpret, or diagnose the statement.","Use the approved urgent channel rather than a normal task queue when the matrix requires it.","Identify the responsible clinician, manager, privacy owner, or other designated role.","Record when the escalation was sent and whether receipt was confirmed.","If the protocol specifies an emergency instruction, use the approved wording exactly.","Stay within the task until ownership has clearly transferred when the protocol requires confirmation."]},{"type":"callout","title":"Never improvise emergency advice","text":"If a patient asks whether to wait, seek emergency care, change medication, or take another clinical action, follow the clinic''s approved emergency or clinical escalation script. Do not create medical advice from your own judgment or from an AI response."},{"type":"heading","text":"Complaint handling"},{"type":"paragraph","text":"A complaint can be acknowledged without admitting fault or promising a remedy. Capture the facts, requested outcome, dates, involved service, and any immediate safety issue. Route the complaint to the designated owner and keep the follow-up visible."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Trying to calm a patient by saying the symptom probably is not serious","Putting an urgent message in a routine inbox because the clinician is busy","Editing the patient''s words into a clinical conclusion","Promising a refund or disciplinary outcome during a complaint","Assuming another staff member saw the escalation without confirming ownership when the SOP requires it"]},{"type":"scenario","title":"Practice scenario","text":"A patient calls to reschedule and says their condition has suddenly worsened. They ask whether they should wait for the new appointment. Describe the words you would avoid, the immediate workflow you would activate, what you would document, and how you would confirm the handoff."},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Do not triage from personal judgment.","Use the practice''s escalation matrix and approved scripts.","Preserve the patient''s wording.","Make transfer of ownership visible."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000052';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Use the practice-management or health-record system as the source of truth","Write factual administrative notes that support auditability","Avoid leaking patient information into side channels","Create handoffs that another staff member can continue immediately"]},{"type":"heading","text":"The system record should explain the work"},{"type":"paragraph","text":"Healthcare administration often crosses email, phone, portals, payer systems, documents, and task queues. The practice record should make the important actions visible without requiring someone to reconstruct your personal inbox or chat history."},{"type":"heading","text":"Good administrative notes"},{"type":"list","items":["State the action taken and factual result.","Include the date or time when it affects the workflow.","Name the destination or queue for a routed item.","Record patient contact attempts according to the practice standard.","Avoid opinions, blame, jokes, speculation, or copied clinical details that are unnecessary for the admin task.","Use the system''s structured status fields when available."]},{"type":"heading","text":"Source-of-truth discipline"},{"type":"steps","items":["Decide which system owns the patient record, appointment, referral, billing item, and task status.","Update that system first or as part of the same workflow.","Link supporting documents rather than maintaining uncontrolled copies.","Keep chat or email as communication, not the only record of the action.","Close a task only when the source record and next step agree."]},{"type":"callout","title":"Do not create a shadow patient record","text":"Personal spreadsheets, notebooks, browser notes, and chat histories can become unauthorized duplicate records. Use them only when the practice has explicitly approved the workflow and retention rules."},{"type":"heading","text":"Handoff format"},{"type":"list","items":["Patient or task reference using the minimum information needed","Current status","Action completed","Outstanding issue","Next owner","Deadline or follow-up time","Escalation already sent, if any","Direct link to the source system when permitted"]},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Writing ''called patient'' with no outcome","Closing a task while the referral or claim is still unresolved","Copying full patient details into team chat","Leaving a sensitive file in downloads after uploading it","Using personal shorthand another staff member cannot understand"]},{"type":"scenario","title":"Practice scenario","text":"At handoff you have an unresolved referral waiting on an attachment, a patient callback request already sent to a nurse, and a payer-status item that needs another follow-up tomorrow. Write a concise handoff that preserves privacy and lets the next staff member continue each item."},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Use one source of truth per workflow.","Write factual, minimal, useful notes.","Avoid shadow records.","A good handoff makes ownership and next action obvious."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000061';

update public.training_lessons
set content='[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Combine privacy, scheduling, referrals, billing, communication, and escalation in one work queue","Prioritize by consequence and ownership rather than message order","Show where administrative authority ends","Produce a clean healthcare handoff"]},{"type":"heading","text":"The simulation"},{"type":"paragraph","text":"You support a fictional multi-provider outpatient clinic. The clinic has written rules for identity verification, scheduling, records release, billing escalation, and urgent clinical messages. Your task is to process the administrative queue without diagnosing, interpreting results, changing clinical documentation, or exposing unnecessary patient information."},{"type":"heading","text":"Work queue"},{"type":"list","items":["A patient wants to reschedule and also asks whether worsening symptoms can wait until next week.","An incoming referral is missing one required attachment.","A payer status response shows a missing subscriber ID.","Another claim response references medical necessity.","A patient asks what a new portal result means.","A billing email disputes the amount charged and asks for an immediate refund.","A staff member accidentally sent a document to the wrong internal recipient.","Tomorrow''s appointment list includes a duplicate-looking patient record.","A records request is ready to send but the destination address differs from the one stored last month.","Three routine reminder messages are ready to send."]},{"type":"heading","text":"Step 1: prioritize"},{"type":"steps","items":["Separate possible urgent clinical or safety issues from routine administration.","Identify privacy or wrong-recipient incidents that require immediate internal escalation.","Identify tasks blocked by specialist judgment.","Handle routine scheduling, reminder, and data-quality work using the SOP.","Assign a visible next owner and time for every unresolved item."]},{"type":"heading","text":"Step 2: produce the work"},{"type":"list","items":["A priority table with reason for order","Administrative action for each queue item","Draft patient messages for at least three appropriate items","Escalation note for the clinical message","Privacy-incident note using facts only","Claims/billing exception notes that show what you can and cannot change","End-of-shift handoff"]},{"type":"callout","title":"The assessment is about judgment, not jargon","text":"You do not earn credit for sounding clinical. You earn credit for moving safe administrative work forward, protecting patient information, escalating correctly, and leaving a traceable record."},{"type":"heading","text":"Common failure patterns"},{"type":"list","items":["Answering the clinical question to be helpful","Sending more patient data than the task needs","Changing a claim or billing field that requires specialist authority","Treating the privacy incident as solved because the recipient deleted the message","Closing items without a next owner or follow-up time"]},{"type":"scenario","title":"Practice scenario","text":"Work through the queue above as if you have 45 minutes left in your shift. Write the first five actions you would take, the two messages you would escalate immediately, and the handoff you would leave for the clinic team."},{"type":"heading","text":"Self-review before submission"},{"type":"list","items":["Did I protect patient information?","Did I keep clinical judgment with clinical staff?","Did I separate administrative corrections from specialist decisions?","Did I make urgent escalation visible?","Did I leave enough evidence for another staff member to continue?"]},{"type":"heading","text":"Key takeaways"},{"type":"list","items":["Safe healthcare administration is structured and traceable.","The VA should be fast on routine work and cautious at clinical or regulated boundaries.","Privacy and escalation are part of the workflow, not afterthoughts.","A strong handoff is part of patient-service quality."]}]'::jsonb,
    is_published=false,
    reviewed_by=null,
    last_reviewed_at=null,
    updated_at=now()
where id='22000003-0000-4000-8000-000000000062';

update public.training_assessments
set instructions='Complete the composite healthcare administration simulation. Submit: (1) a prioritized work queue with reasons, (2) safe administrative actions for every item, (3) at least three patient-facing administrative messages, (4) a clinical escalation note that preserves the patient''s wording, (5) a privacy-incident note, (6) claims and billing exception notes that clearly separate administrative corrections from coding, coverage, or medical-necessity decisions, and (7) an end-of-shift handoff. Review is based on privacy, administrative accuracy, escalation judgment, communication clarity, and traceability. Do not provide diagnosis, clinical advice, treatment recommendations, prescribing guidance, coding judgment, or legal interpretation.',
    pass_score=80,
    is_published=false,
    updated_at=now()
where id='23000000-0000-4000-8000-000000000003';
